const input = $input.first().json;
const body = input.body && typeof input.body === 'object' ? input.body : {};
const data = body.data && typeof body.data === 'object' ? body.data : {};
if (body.event !== 'message.sent') return [];
const to = String(data.to || '').trim();
if (!to || to.endsWith('@g.us')) return [];
let customerId = to.replace(/\D/g, '');
if (customerId.startsWith('01') && customerId.length === 11) customerId = '88' + customerId;
const content = String(data.message || '').trim().slice(0, 12000);
const sessionId = String(body.sessionId || '').trim();
const messageId = String(data.messageId || body.id || '').trim();
if (customerId.length < 7 || customerId.length > 15 || !content || !sessionId) return [];
return [{ json: {
  memory_session_id: `whatsapp:${sessionId}:${customerId}`,
  memory_message: {
    type: 'ai',
    content,
    additional_kwargs: {
      source: 'wafastapi_sent_sync',
      message_id: messageId,
      historical: false,
    },
    response_metadata: {},
    invalid_tool_calls: [],
  },
} }];

const input = $input.first().json;
const body = input.body && typeof input.body === 'object' ? input.body : {};
const data = body.data && typeof body.data === 'object' ? body.data : {};

if (body.event !== 'message.received') return [];

let customerId = String(data.from || '').replace(/\D/g, '');
if (customerId.startsWith('01') && customerId.length === 11) customerId = '88' + customerId;
const rawMessage = String(data.message || '').trim();
const hasMedia = Boolean(data.mediaUrl || data.mimeType || data.fileName || data.ocrText || data.ocrMethod);
const message = rawMessage.slice(0, hasMedia ? 12000 : 2000);
const messageId = String(data.messageId || body.id || '').trim();
const sessionId = String(body.sessionId || '').trim();
if (customerId.length < 7 || customerId.length > 15 || !message || !sessionId) return [];

const state = $getWorkflowStaticData('global');
const now = Date.now();
const maxAge = 24 * 60 * 60 * 1000;
state.seen = state.seen && typeof state.seen === 'object' ? state.seen : {};
for (const [key, timestamp] of Object.entries(state.seen)) {
  if (now - Number(timestamp) > maxAge) delete state.seen[key];
}
const dedupeKey = sessionId + ':' + (messageId || body.id || customerId + ':' + message);
if (state.seen[dedupeKey]) return [];
state.seen[dedupeKey] = now;

return [{ json: {
  customer_id: customerId,
  message,
  message_id: messageId,
  session_id: sessionId,
  webhook_event_id: String(body.id || ''),
  has_media: hasMedia,
  media_url: String(data.mediaUrl || ''),
  media_type: String(data.mimeType || data.type || ''),
  media_filename: String(data.fileName || ''),
  ocr_text: String(data.ocrText || '').slice(0, 12000),
  extraction_method: String(data.ocrMethod || 'NONE'),
  has_media: hasMedia,
  media_url: String(data.mediaUrl || ''),
  media_type: String(data.mimeType || data.type || ''),
  media_filename: String(data.fileName || ''),
  ocr_text: String(data.ocrText || '').slice(0, 12000),
  extraction_method: String(data.ocrMethod || 'NONE'),
  has_media: hasMedia,
  media_url: String(data.mediaUrl || ''),
  media_type: String(data.mimeType || data.type || ''),
  media_filename: String(data.fileName || ''),
  ocr_text: String(data.ocrText || '').slice(0, 12000),
  extraction_method: String(data.ocrMethod || 'NONE'),
} }];

const agent = $input.first().json;
const inbound = $('Filter and Deduplicate').first().json;
const generated = String(agent.reply || '').trim();
const reply = generated || 'দুঃখিত, আমাদের স্বয়ংক্রিয় সেবা এই মুহূর্তে সাময়িকভাবে বন্ধ রয়েছে। আমাদের দলের একজন সদস্য আপনার বার্তাটি দেখে যত দ্রুত সম্ভব উত্তর দেবেন।';
if (!inbound.customer_id || !reply) return [];
return [{ json: {
  customer_id: inbound.customer_id,
  message_id: inbound.message_id,
  session_id: inbound.session_id,
  reply: reply.slice(0, 1000),
  agent_success: Boolean(generated),
  agent_reason: agent.reason || (generated ? 'ok' : 'agent_unavailable'),
} }];

const item = $('Filter and Deduplicate').first().json;
if (!item.customer_id || !item.session_id || !item.message) return [];
return [{ json: { memory_session_id: `whatsapp:${item.session_id}:${item.customer_id}`, memory_message: { type: 'human', content: String(item.message).slice(0, 12000), additional_kwargs: { source: 'wafastapi_received_learning', message_id: item.message_id, media_url: item.media_url || '', media_type: item.media_type || '', media_filename: item.media_filename || '', extraction_method: item.extraction_method || 'NONE', historical: false }, response_metadata: {} } } }];
